//! 库存对账核心逻辑。

use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StockRow {
    pub sku: String,
    pub name: String,
    pub quantity: i64,
}

/// 解析库存与流水并计算期末库存。
///
/// 两个输入都是 UTF-8 CSV 文本，首行为表头，允许 CRLF 行尾与末尾空行。
pub fn reconcile(stock_csv: &str, movements_csv: &str) -> Result<Vec<StockRow>, String> {
    let mut rows: Vec<StockRow> = Vec::new();
    let mut index: HashMap<String, usize> = HashMap::new();

    for (lineno, line) in data_lines(stock_csv) {
        let mut fields = line.splitn(3, ',');
        let sku = fields.next().unwrap_or("").trim();
        let name = fields.next().unwrap_or("").trim();
        let quantity = fields.next().unwrap_or("").trim();
        if sku.is_empty() {
            return Err(format!("库存表第 {lineno} 行缺少 SKU"));
        }
        let quantity: i64 = quantity.parse().map_err(|_| {
            format!("库存表第 {lineno} 行 SKU {sku} 的数量无法解析为整数: {quantity}")
        })?;
        if index.contains_key(sku) {
            return Err(format!("库存表中 SKU {sku} 重复出现（第 {lineno} 行）"));
        }
        index.insert(sku.to_string(), rows.len());
        rows.push(StockRow { sku: sku.to_string(), name: name.to_string(), quantity });
    }

    for (lineno, line) in data_lines(movements_csv) {
        let mut fields = line.splitn(2, ',');
        let sku = fields.next().unwrap_or("").trim();
        let delta = fields.next().unwrap_or("").trim();
        let delta: i64 = delta.parse().map_err(|_| {
            format!("流水表第 {lineno} 行 SKU {sku} 的变动量无法解析为整数: {delta}")
        })?;
        let pos = index.get(sku).copied().ok_or_else(|| {
            format!("流水表第 {lineno} 行引用了不存在的 SKU: {sku}")
        })?;
        rows[pos].quantity += delta;
    }

    for row in &rows {
        if row.quantity < 0 {
            return Err(format!("SKU {} 的期末库存为负库存: {}", row.sku, row.quantity));
        }
    }

    rows.sort_by(|a, b| a.sku.cmp(&b.sku));
    Ok(rows)
}

