fn data_lines(csv: &str) -> impl Iterator<Item = (usize, &str)> {
    csv.lines()
        .enumerate()
        .skip(1)
        .map(|(i, line)| (i + 1, line.trim_end_matches('\r')))
        .filter(|(_, line)| !line.trim().is_empty())
}
```

Note `str::lines` already strips trailing `\r`? Yes! Rust's `lines()` splits on `\n` and strips a trailing `\r`. So CRLF handled automatically. But keeping trim_end_matches('\r') is harmless.

